import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { collection, query, where, onSnapshot, updateDoc, getDocs, orderBy } from 'firebase/firestore';
import { db, auth } from '../../firebase';
import { onAuthStateChanged } from 'firebase/auth';

const ChatListPage = () => {
  const [user, setUser] = useState(null);
  const [chats, setChats] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      // Query chats where the current user is a participant
      const q = query(
        collection(db, 'chats'),
        where('participants', 'array-contains', user.uid),
        orderBy('lastTimestamp', 'desc')
      );

      const unsubscribe = onSnapshot(
        q,
        (querySnapshot) => {
          const chatList = querySnapshot.docs.map((doc) => ({
            id: doc.id,
            ...doc.data(),
          }));

          // Sort chats by last timestamp (descending)
          setChats(chatList);
        },
        (error) => {
          console.error('Error fetching chats:', error);
        }
      );

      return () => unsubscribe();
    }
  }, [user]);

  const handleChatClick = async (chat) => {
    console.log('Navigating to chat with conversationId:', chat.id);

    // Mark all unread messages in this conversation as read
    try {
      const messagesQuery = query(
        collection(db, 'chats', chat.id, 'messages'),
        where('isRead', '==', false),
        where('recipientId', '==', user.uid)
      );

      const querySnapshot = await getDocs(messagesQuery);
      querySnapshot.forEach(async (doc) => {
        await updateDoc(doc.ref, { isRead: true });
      });
    } catch (error) {
      console.error('Error marking messages as read:', error);
    }

    // Navigate to the chat details
    navigate(`/chat/${chat.postId}`, {
      state: {
        conversationId: chat.id,
        postId: chat.postId,
      },
    });
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-2xl font-semibold mb-4">Chats</h1>
      <div className="bg-white p-4 rounded-lg shadow-md">
        {chats.length > 0 ? (
          chats.map((chat) => (
            <div
              key={chat.id}
              className="mb-2 p-2 rounded-lg bg-gray-100 cursor-pointer"
              onClick={() => handleChatClick(chat)}
            >
              <p className="text-sm font-bold">
                {chat.participants.find((participant) => participant !== user.uid)}
              </p>
              <p className="text-sm text-gray-600">{chat.lastMessage}</p>
              <small className="text-gray-400">
                {new Date(chat.lastTimestamp.seconds * 1000).toLocaleString()}
              </small>
              {chat.hasNewReply && (
                <span className="text-xs text-red-500 font-semibold">New Reply</span>
              )}
            </div>
          ))
        ) : (
          <p className="text-gray-600">No chats available</p>
        )}
      </div>
    </div>
  );
};

export default ChatListPage;
